        "evaluatedFiscalYear": 2024,
        "evaluationYear": null,
        "proofStart": 13666,
        "proof": "の墳\n丘長が100mを超えるものと判明し、また\n町内では初めてとなる陸橋を検出した。\n○地元や関係団体の協力を得て、旧北岡田\n家住宅を37日公開し、836人が来場した。\nまた、国民文化祭イベントとして「大正\n昭和体験ツアー」の開催や、美濃大野観\n光ガイド隊などヘ会場提供し、67人を受\nけ入れる等、文化財をより多くの方々に\n見て触れていただくことができた。\n\n文化財の調\n\n◇開発に係る埋蔵文化財の発\n\n○埋蔵文化財の試掘確認調査等を実施し、\n\n査、再評価\n\n掘調査の実施と成果の公表\n\n土地開発事業者との調整を行った。\n\n◇町内に所在する有形無形の文 ○学識者による調査（来振寺の仏",
