        "proof": "，年齢を問わず町民が文化的に関わることが出来る\n機会をしっかり確保していくことが必要である\n→ジュニア文化サークル，文化事業，夏休み親子教室，短期教室\nの魅力ある企画作りと内容の充実を図った。\n↓\n○ジュニア文化サークル活動は，大きく評価されている。今後も続\nけられるよう望む。回を重ねるごとに，優れた成果を残している。\n▲多くの幼児，児童，生徒が希望通り参加できる枠組みを作ること\nが必要である。\nH30▲教えていただく方も高齢化により減少する心配がある。引き\n\n評価\n\nＣ\n\nＡ\n\nＡ\n\n継ぎと後継者の育成の必要性を感じる。\n\nの継承・発 営や多角的な文 →町民の関心を高めるための魅力ある展示の工夫"
