        "proof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.8\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n単\n\n【所管課評価】\n【対象者等からの評価】\n\n水道事業会計補助事業\n\n①在宅勤務・外出自粛に伴う在宅時間の長期化による水\n\n【水道環境課】\n\n道使用量の増加、事業所の休業等により生じる経済的負\n\n33,815,970\n\n8月分\n\n4,217,660円（2,938件）\n\n新型コロナウイルス感染症による町民\n\n担を軽減するため\n\n9月分\n\n4,230,750円（2,935件）\n\nの経済的な影響の経済的負担の軽減につ\n\n②水道事業会計に補助し、水道料金（基本料金）の免除\n\n10月分 4,214,850円（2,933件）\n\nに要する経費（水道料金の基本料金の免除に伴う減収補\n\n11月分 4,215,730円（2,934件）\n\n填）に充当\n\n12月分 4,217,490円（2,935件）\n\n【対象者等からの評価】\n\n③4,222,000円／月×5ヶ月分\n\n1月分\n\n4,233,390円（2,937件）\n\n・基本料金の免除により、家計の負担軽\n\n4,250,000円／月×3ヶ月分\n\n2月分\n\n4,241,730円（2,942件）\n\n減につながりよかった。\n\n3月分\n\n4,244,370円（2,944件）\n\n④関ケ原町水道事業会計\n2\n\n効果検証\n実施状況\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n1\n\n①目的・効果\n\n新型コロナウイルス感染症拡大防止協力 ①新型コロナウイルス感染症拡大防止のため\n\nR2.6\n\nR3.3\n\n7,683,304\n\n27,717,000 ・水道事業会計補助金\n\n【所管課評価】\n\nながった。\n\n7,365,000 ・新型コロナウイルス感染症拡大防止協 【所管課評価】\n\n金事業\n\n②県の要請や協力依頼に応じて、施設の使用停止や営業\n\n力金（第1弾）\n\n【地域振興課】\n\n時間の短縮に全面的に協力した事業者に対する岐阜県新\n\n45件分 7,383,304円\n\n新型コロナウィルス感染症拡大におい\nて県の要請により営業停止や営業時間の\n\n型コロナウイルス感染症拡大防止協力金の町負担分に充\n\n短縮を余儀なくされた事業者にとって事\n\n当\n\n業継続の資金となり地域経済にとっても\n\n③県試算より\n\n非常に有効な支援となった。\n\n④岐阜県\n3\n\n単\n\n子育て世帯応援給付金給付事業\n\n①新型コロナウイルス感染症の影響を受けている子育て\n\n【住民課】\n\n世帯の生活を支援するため\n\nR2.6\n\nR3.3\n\n16,467,457\n\n15,786,000 ・子育て応援給付金給付金\n821人 16,420,000円\n\n②③18歳以下の児童がいる世帯に対し、児童1人につき2\n\n【所管課評価】\n新型コロナウイルス感染症拡大の影響\nによる感染予防対策として、各家庭にお\n\n万円を給付する経費に充当\n\n・事務費（封筒・郵便料） 47,457円\n\n・給付金 20,000円／人×850人\n\nける感染予防にかかる経済的負担を軽減\nすることができた。\n\n・事務費 600,000円（郵便料、手数料等）\n④18歳以下の児童がいる世帯\n\n【対象者等からの評価】\n・特に申請手続きの必要がなかったの\nで、ありがたかった。\n・消毒液やマスクなどの購入費用にあて\nることができた。\n\n4\n\n単\n\n関ケ原町プレミアム商品券発行事業\n\n①落ち込んだ地域内の消費を取り戻すため町内事業所で\n\n【地域振興課】\n\n使用できるプレミアム付き商品券を発行\n\nR2.6\n\nR3.3\n\n10,000,000\n\n9,586,000 ・プレミアム商品券発行事業補助金\n10,000,000円\n\n【所管課評価】\n新型コロナウイルス感染症の影響によ\n\n②③プレミアム商品券発行事業に要する経費に充当（補\n\nり落ち込んでいた町内事業所で買い物す\n\n助金）\n\nる機会が増え、地域経済の活性化に繋\n\n・プレミアム商品券発行事業補助金 10,000,000円\n\nがった。\n\n（プレミアム分換金費用、各店舗取扱手数料、商品券印\n刷費、チラシ印刷費等、郵送代等事務経費）\n\n【対象者等からの評価】\n\n④町商工会\n\n・町民の関心も高く、町内で買い物する\n機会が増えてよかった。\n\n\n",
