        "proof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.6\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n効果検証\n実施状況\n\n【所管課評価】\n【対象者等からの評価】\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n5\n\n①目的・効果\n\n新生児臨時特別給付金給付事業\n\n①国の特別定額給付金対象世帯との均衡や子育てに係る\n\n【住民課】\n\n経済負担の軽減を図るため\n\n1,200,000\n\n1,150,000 ・新生児臨時特別給付金\n12人 1,200,000円\n\n【所管課評価】\n新型コロナウイルス感染症の蔓延によ\n\n②③国の特別定額給付金の基準日を過ぎて生まれた子ど\n\nり、経済的な影響を抱える町民に対して\n\nも1人に対し、10万円を支給する経費に充当\n\n給付された特別定額給付金の基準日以降\n\n・支援金 100,000円×25人\n\nに出生した町民にも支給し、町民の生活\n\n④基準日以降に出生した子どもがいる世帯\n\n支援につながった。\n【対象者等からの評価】\n・手続きは分かりやすくありがたかっ\nた。\n・国の給付対象ではなかったが、町から\n支給されてうれしかった。\n\n6\n\n単\n\n新型コロナウイルス感染症感染防止対策 ①町内事業所の新型コロナウイルス感染症防止対策の推\n\nR2.6\n\nR3.3\n\n3,480,000\n\n3,336,000 ・新型コロナウイルス感染症感染防止対 【所管課評価】\n\n協力金事業\n\n進及び利用者等の新型コロナウイルス感染症予防に対す\n\n策協力金\n\n【地域振興課】\n\nる意識啓発を図るため\n\n116事業所 3,480,000円\n\nどの業種の事業所でも早急に新型コロ\nナウイルス感染症対策を施す必要があっ\n\n②③感染症予防対策を実施する事業者に対する協力金に\n\nたことから、申請手続き等を簡素化し、\n\n充当\n\n多くの事業所において新型コロナウイル\n\n・協力金 30,000円×300事業所\n\nス感染症対策が実施された。\n\n④町内事業所\n【対象者等からの評価】\n・手続きが簡単だったので、制度を利用\nしようと思えた。\n・売上が無い中で新型コロナウイルスス\n対策にも費用がかかるので、この制度が\nあってよかった。\n7\n\n単\n\n公共施設感染防止対策事業（備品整備事 ①公共施設における新型コロナウイルス感染症の感染リ\n\nR2.6\n\nR3.3\n\n5,746,812\n\n5,509,000 ・サーモグラフィーカメラ設置（庁舎・ 【所管課評価】\n\n業）\n\nスクの軽減、拡大防止を図るため\n\nふれあいセンター・診療所・歴史民俗学\n\n【総務課】\n\n②③赤外線サーモグラフィーカメラの設置等の感染防止\n\n習館） 5基 4,620,000円\n\n【教育課】\n\n対策に要する経費に充当\n・サーモグラフィーカメラ設置（7,480,000円）\n\n各施設にサーモグラフィーカメラを設\n置することにより、利用者の健康状態を\n把握し、感染防止対策を進めることがで\n\n・ふれあい図書館備品\n\nきた。また、画面表示部のデジタルサイ\n\n図書消毒機（1台） 770,000円\n\nネージを利用し、新型コロナウイルス感\n\n館・図書館）2、診療所1、歴史民俗学習館1）\n\nブックラック（3台） 169,950円\n\n染防止の啓発を図ることができた。\n\n・ふれあい図書館備品（1,214,510円）\n\nワゴン（3台） 126,720円\n\n1,496,000円×5基（庁舎1、ふれあいセンター（町民会\n\n図書消毒機 770,000円×1台、スチールブックラック\n71,280円×3個、ワゴン（返本用） 54,120円×3台、本\nの返却ポスト 35,310円、サーキュレーター 11,000円\n×3台\n④役場庁舎、関ケ原診療所 他\n\nふれあい図書館に各種備品を導入する\n\n返却ポスト（1台） 27,142円\n\nことにより、３密の回避や除菌など利用\n\nサーキュレーター（3台） 33,000円\n\n者の安全確保を図ることができた。\n\n\n"