        "periodProof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.8\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n効果検証\n実施状況\n\n【所管課評価】\n【対象者等からの評価】\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n11\n\n①目的・効果\n\n地域産品等販売用ネットショップ開設事 ①外出自粛時等における地域産品等の販路拡大のため\n\n998,250\n\n957,000 ・地域産品等販売用ネットショップ開設 【所管課評価】\n\n業\n\n②③外出自粛時等においても、地域産品等をオンライン\n\n事業委託料（観光協会）\n\n【地域振興課】\n\n上で販売できるネットショップを開設する経費（駅前観\n\n998,250円\n\nこれまでは現地に来てモノを買ってい\nただくことに重点を置いていたが、コロ\n\n光交流館をオンライン上で開設）に充当\n\nナをきっかけに、ネットショップを開設\n\n・地域産品等販売用ネットショップ開設事業委託料\n\nしたことで、普段来られない遠方のお客\n\n1,000,000円\n\n様に喜んでいただき、オンラインショッ\n\n企画・調整費、ホームページ改修、広告料、チラシ・\n\nプのメリットが実感できた。\n\nポスター制作、ノベルティー制作、撮影費、備品購入、\n消耗品、管理費他\n④関ケ原観光協会（事業委託）\n12\n\n単\n\n避難所生活環境確保事業\n\n①避難所における新型コロナウイルス感染症対策を強化\n\n【総務課】\n\nするため\n\nR2.6\n\nR3.3\n\n5,597,680\n\n2,684,000 ・避難所資機材購入\n手指消毒剤（500本） 632,500円\n\n【所管課評価】\n\n②避難所に配備する資機材の購入に要する経費に充当\n\n体温計（26本） 214,500円\n\nや、避難者間の距離確保を目的とした資\n\n③手指消毒剤の購入（1,375円×500本）\n\n避難所において使用する手指消毒剤等\n\nウエットティッシュ 29,700円\n\n機材を導入したことによって災害発生時\n\n体温計の購入（3,850円×70本）\n\n使い捨て手袋 42,900円\n\nにおける避難所内での新型コロナウイル\n\nウエットティッシュ（198円×150袋）\n\nトイレ用テント（26個） 629,200円\n\nス感染症拡大防止のための準備が整っ\n\n使い捨て手袋（1,430円×30箱）\n\n非常用排便収納袋（26セット）\n\nた。\n\nトイレ用テント（24,200円×26個）\n\n652,080円\n\n非常用排便収納袋（25,080円×26セット）\n\n非常用便座（26台） 128,700円\n\n非常用便座（4,950円×26台）\n\n間仕切りテント（45個） 767,250円\n\n間仕切りテント（17,050円×45個）\n\nワンタッチイベントテント（13個）\n\nワンタッチイベントテント（176,000円×13個）\n\n1,485,000円\n\nアルミハイスタンド扇風機（8,030円×16台）\n\nアルミハイスタンド扇風機（16台）\n\nフェイスシールド（330円×500枚）\n\n127,600円\n\nポリエチレン製ガウン（220円×500枚）\n\nフェイスシールド（500枚）\n\n段ボールベッド（10,450円×50台）\n\n165,000円\n\nビニールシート（18,150円×5ロール）\n\nポリエチレン製ガウン（500枚）\n\n④町指定避難所\n\n110,000円\n段ボールベッド（50台） 522,500円\nビニールシート 90,750円\n\n13\n\n単\n\n（コンビニ収納サービス及び）キャッ\n\n①公共料金の窓口納付等の接触機会の軽減を図るため\n\nシュレス決済導入事業\n\n②③公共料金のキャッシュレス決済の導入に要する経費\n\n【総務課】\n\nに充当\n・システム改修等委託料 5,000,000円\n\nR2.9\n\nR3.3\n\n4,702,128\n\n4,508,000 ・総合行政情報システム改修委託料\n4,493,128円\n\n24時間いつでもどこからでも納付する\nことができるキャッシュレス決済導入\n\n・回線開通業務委託料 55,000円\n\n・専用プリンター 77,000円×2台\n④役場庁舎\n\n【所管課評価】\n\n後、利用者も増加しており窓口納付によ\nる接触機会の軽減に役立っている。\n\n・専用プリンター 154,000円\n\n\n",
