        "proof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.9\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n効果検証\n実施状況\n\n【所管課評価】\n【対象者等からの評価】\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n17\n\n①目的・効果\n\n体験型プログラム及び関ケ原検定感染防 ①歴史民俗学習館及び笹尾山交流館等で実施する体験型\n\n2,602,353\n\n2,495,000 ・体験型プログラム\n\n【所管課評価】\n\n止対策事業\n\nプログラム（瓦作り等）を感染防止しながら実施するた\n\nフェイスシールド（100個） 33,000円\n\n【地域振興課】\n\nめ。また、例年実施してきた「関ケ原検定」を感染防止\n\nアクリル板（10枚） 93,500円\n\n体験型プログラムを実施することで、コ\n\nのため、会場に集合して受検する形ではなく、自宅で気\n\n体験キット 1,006,500円\n\nロナ禍においても観光客等の集客が可能\n\n軽に受検できる仕組みを構築するため\n\n十分な感染防止対策実施したうえで、\n\nとなり、地域経済の活性化につながっ\n\n②感染防止のための用具、体験キット等の購入費用及び\n\n・関ケ原検定\n\n自宅での受検の仕組みを構築するための経費に充当（関\n\n公式本作成 935,000円\n\nた。\nまた、新型コロナウイルス感染症対策\n\nケ原をPRする参加賞含む）\n\n問題作成 207,900円\n\nとして、関ケ原検定を自宅で受検できる\n\n③（1）体験型プログラム\n\n参加賞 242,440円\n\nようになり、自宅時間が増えている中で\n\n・フェイスシールド（330円×100個）\n\n郵送代 35,739円\n\n関ケ原を知っていただく機会が作れた。\n\n・アクリル板（仕切り用）（10,000円×10枚）\n\n事務経費 48,274円\n\n・体験キット（材料費等）（1,080,000円）\n（2）関ケ原検定\n・公式本作成代（1,000,000円）\n・問題作成代等（207,900円）\n・参加賞、認定証（250,000円）\n・郵送代（50,000円）\n・事務経費（50,000円）\n④歴史民俗資料館 他\n18\n\n単\n\n町内飲食店等周遊デジタルスタンプラ\n\n①観光協会が運営する「関ケ原ファンクラブ」のデジタ\n\nリー実施事業\n\nル基盤を町内飲食店等も活用できる形で再構築し、同基\n\nR2.9\n\nR3.3\n\n2,976,600\n\n2,853,000 ・町内飲食店等周遊デジタルスタンプラ 【所管課評価】\nリー実施事業委託料（観光協会）\n\n【地域振興課】\n\n盤を用いて、町内飲食店等への周遊を促すデジタルスタ\n\n2,976,600円\n\n新型コロナウイルス対策として、直接\n手を触れずにスタンプを集められ、参加\n\nンプラリーを実施。また、アフターコロナを見据え、来\n\nする店舗や利用者も安心して周遊するこ\n\n年度以降も同基盤を用いて、町内飲食店等が参加できる\n\nとができた。また、デジタル化を活性化\n\nデジタルサービスの展開（ポイント付与制度等）を視野\n\nすることで、今後の事業にも活用できる\n\nに入れて、整備を図る\n\n仕組みが構築されたので、観光客が戻っ\n\n②③関ケ原ファンクラブのデジタル基盤に町内各店舗の\n\nてきたときに、楽しく町内を周遊できる\n\nQRコード等を組み込み、モバイルラリーの機能を付加す\n\n環境が整った。\n\nる経費に充当\n・町内飲食店等周遊デジタルスタンプラリー実施事業委\n託料 3,000,000円\nシステム構築費、ラリー運用費、ラリー用QRコード作\n成費、広告費、管理費他\n④関ケ原観光協会（事業委託）\n\n\n",
