        "proof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.9\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n効果検証\n実施状況\n\n【所管課評価】\n【対象者等からの評価】\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n19\n\n①目的・効果\n\n携帯端末による多言語表示対応業務（各 ①町内の各史跡のサインについて、感染を防ぎながら、\n\n9,130,000\n\n8,752,000 ・携帯端末による多言語表示対応業務委 【所管課評価】\n\n史跡サインの内容を文字及び音声で翻\n\n多言語表示のデジタルサービスを提供するため（ガイド\n\n託料\n\n訳）\n\nによる通訳等は感染のリスクがあるため、携帯端末で各\n\n9,130,000円\n\n非接触型で日本語も含め、多言語情報\n\n【地域振興課】\n\n自が読みこむ形で翻訳サービスを提供し、非接触型の多\n\nし、感染防止対策につながった。今後の\n\n言語化対応を図る（※非接触型翻訳サービス））\n\n外国人観光客の誘客に対するサービス基\n\n②③町内の史跡サインにあるQRコードを各旅行者の携帯\n\n盤の整備を図ることができた。\n\nを提供することで、接触機会を少なく\n\n端末等で読み込むと５か国語（英、仏、中（簡・繁）、\n韓）で文字及び音声案内を行うサービスを構築する経費\nに充当（英語は史跡サインに文字が掲載済みのため、音\n声のみ構築）\n・携帯端末による多言語表示対応業務委託料 9,196,000\n円\n翻訳費5か国語、QRコードガイドシステム、シール制\n作、音声データ制作、データ登録、設置・工事費、管理\n費他\n④町内各史跡\n20\n\n単\n\n観光施設多言語情報提供業務\n\n①新型コロナ収束後の外国人観光客増加も見据え、関ケ\n\n【地域振興課】\n\n原町歴史民俗学習館のHPについて、多言語（英語）によ\n\nR2.9\n\nR3.3\n\n3,190,000\n\n3,058,000 ・観光施設多言語情報提供業務委託料\n3,190,000円\n\n【所管課評価】\nコロナ後の外国人観光客の誘客に対す\n\nる情報提供を行うため\n\nるサービスの基盤を整備することができ\n\n②③歴民のHPを英語に翻訳する経費に充当\n\nた。\n\n・観光施設多言語情報提供業務委託料 3,201,000円\n翻訳費、Webデザイン費、Webコーディング費、情報\n掲載、管理費他\n④歴史民俗学習館\n\n21\n\n単\n\n多言語デジタルサービス提供業務\n\n①感染防止対策のため、町内の観光情報等を紙によるパ\n\n【地域振興課】\n\nンフレットではなく、デジタルで多言語（9言語）による\n\nR2.9\n\nR3.3\n\n497,310\n\n477,000 ・多言語デジタルサービス提供事業委託 【所管課評価】\n料 497,310円\n\nデジタルでの観光情報の提供により、\n\n提供を行うため\n\n接触機会を少なくし、感染防止対策につ\n\n②③9言語観光サイトにアクセスするためのQRコードを\n\nながった。コロナ後の外国人観光客の誘\n\n付与したカードを作成する費用（JTBが提供する「9言語\n\n客に対するサービス基盤の整備を図るこ\n\n観光サイトＪＦＭ」のサービスを利用。観光パンフレッ\n\nとができた。\n\nトと同種の内容をデジタルに提供。観光客は町内各所等\nに置かれたカードから、観光情報等を携帯端末で読み込\nむ。）\n・多言語デジタルサービス提供事業委託料 500,000円\nカード作成費用、管理費他\n④JTB（事業委託）\n\n\n",
