        "evaluatedFiscalYear": 2020,
        "evaluationYear": null,
        "proofStart": 12139,
        "proof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.9\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n効果検証\n実施状況\n\n【所管課評価】\n【対象者等からの評価】\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n22\n\n①目的・効果\n\n家賃支援給付金事業\n\n①緊急事態宣言の延長等により、売上の減少に直面する\n\n【地域振興課】\n\n事業者の事業継続を下支えするため\n\n1,766,000\n\n1,693,000 ・家賃支援給付金事業補助金\n13事業所 1,766,000円\n\n【所管課評価】\n国の事業に上乗せして補助すること\n\n②③国が実施する家賃支援給付金の事業者負担分を補助\n\nで、事業者の負担を大幅に軽減すること\n\nする\n\nができ、事業継続を支援することができ\n\n・国から給付された給付金額×1/2\n\nた。\n\n（法人1,800,000円、個人900,000円を上限）\n④町内事業者\n\n【対象者等からの評価】\n・売上が無い中、固定費を支払うのは困\n難だが、この補助制度を活用することで\n継続して店を運営できている。\n\n23\n24\n\n25\n\n【欠番】\n単\n\n単\n\n公共的空間安全・安心確保事業\n\n①議員間、理事者間の距離を確保し、密集場所における\n\n【議会事務局】\n\n感染リスクの軽減を図るため\n\nR2.9\n\nR3.3\n\n6,809,000\n\n6,527,000 ・音響設備 6,809,000円\n\n【所管課評価】\n音響設備が有線から無線になったこと\n\n②③議場(大会議室）音響設備を有線から赤外線タイプへ\n\nで、議員及び理事者の座席の間隔を十分\n\nの改修に要する経費に充当\n\nに確保することができ、密集場所におけ\n\n・音響設備 6,985,000円\n\nる感染リスクの軽減を図ることができ\n\n④役場庁舎\n\nた。\n\n避難所における新型コロナ感染拡大防止 ①想定収容人数の多い避難所において、感染拡大防止を\n\nR2.9\n\nR3.3\n\n2,809,400\n\n2,693,000 ・水道事業会計補助金 2,809,400円\n\n【所管課評価】\n\n事業\n\n目的とした手洗い等に利用する水を確保するため\n\n【水道環境課】\n\n②③水道事業会計へ補助し、組立式給水タンク及び運搬\n\n組立式給水タンク 594,000円\n\nの基本的な感染予防を行うために必要な\n\n用の車両搭載型可搬式給水タンクの整備に要する経費に\n\n給水タンク 2,046,000円\n\n水の確保に必要な給水タンクが整備を図\n\n充当\n\n発電機 169,400円\n\nることができた。また、車両搭載型可搬\n\n・水道事業会計補助金\n\n避難所等において、手洗い・うがい等\n\n式給水タンクの整備により車両が通れる\n\n組立式給水タンク（1,000ℓ） 594,000円×1基\n\n場所には応急給水ができるようになっ\n\n車両搭載型可搬式給水タンク（800ℓ） 2,090,000円\n\nた。\n\n×1基\n発電機 169,400円×1台\n④浄水場\n\n\n",
        "periodProof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.9\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n効果検証\n実施状況\n\n【所管課評価】\n【対象者等からの評価】\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n22\n\n①目的・効果\n\n家賃支援給付金事業\n\n①緊急事態宣言の延長等により、売上の減少に直面する\n\n【地域振興課】\n\n事業者の事業継続を下支えするため\n\n1,766,000\n\n1,693,000 ・家賃支援給付金事業補助金\n13事業所 1,766,000円\n\n【所管課評価】\n国の事業に上乗せして補助すること\n\n②③国が実施する家賃支援給付金の事業者負担分を補助\n\nで、事業者の負担を大幅に軽減すること\n\nする\n\nができ、事業継続を支援することができ\n\n・国から給付された給付金額×1/2\n\nた。\n\n（法人1,800,000円、個人900,000円を上限）\n④町内事業者\n\n【対象者等からの評価】\n・売上が無い中、固定費を支払うのは困\n難だが、この補助制度を活用することで\n継続して店を運営できている。\n\n23\n24\n\n25\n\n【欠番】\n単\n\n単\n\n公共的空間安全・安心確保事業\n\n①議員間、理事者間の距離を確保し、密集場所における\n\n【議会事務局】\n\n感染リスクの軽減を図るため\n\nR2.9\n\nR3.3\n\n6,809,000\n\n6,527,000 ・音響設備 6,809,000円\n\n【所管課評価】\n音響設備が有線から無線になったこと\n\n②③議場(大会議室）音響設備を有線から赤外線タイプへ\n\nで、議員及び理事者の座席の間隔を十分\n\nの改修に要する経費に充当\n\nに確保することができ、密集場所におけ\n\n・音響設備 6,985,000円\n\nる感染リスクの軽減を図ることができ\n\n④役場庁舎\n\nた。\n\n避難所における新型コロナ感染拡大防止 ①想定収容人数の多い避難所において、感染拡大防止を\n\nR2.9\n\nR3.3\n\n2,809,400\n\n2,693,000 ・水道事業会計補助金 2,809,400円\n\n【所管課評価】\n\n事業\n\n目的とした手洗い等に利用する水を確保するため\n\n【水道環境課】\n\n②③水道事業会計へ補助し、組立式給水タンク及び運搬\n\n組立式給水タンク 594,000円\n\nの基本的な感染予防を行うために必要な\n\n用の車両搭載型可搬式給水タンクの整備に要する経費に\n\n給水タンク 2,046,000円\n\n水の確保に必要な給水タンクが整備を図\n\n充当\n\n発電機 169,400円\n\nることができた。また、車両搭載型可搬\n\n・水道事業会計補助金\n\n避難所等において、手洗い・うがい等\n\n式給水タンクの整備により車両が通れる\n\n組立式給水タンク（1,000ℓ） 594,000円×1基\n\n場所には応急給水ができるようになっ\n\n車両搭載型可搬式給水タンク（800ℓ） 2,090,000円\n\nた。\n\n×1基\n発電機 169,400円×1台\n④浄水場\n\n\n",
