        "proof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.6\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n効果検証\n実施状況\n\n【所管課評価】\n【対象者等からの評価】\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n29\n\n①目的・効果\n\n公共施設感染防止対策事業（換気対策事 ①公共施設における新型コロナウイルス感染症の感染リ\n\n3,207,710\n\n3,075,000 ・網戸設置工事\n\n【所管課評価】\n\n業）\n\nスクの軽減、拡大防止を図るため\n\n子育てコミュニティー事業 80,520円\n\n【住民課】\n\n②③換気対策として実施する網戸の設置に要する経費に\n\n東保育園 502,150円\n\n気対策を徹底し、新型コロナウイルス感\n\n各施設に網戸を設置することにより換\n\n【教育課】\n\n充当\n\n西保育園 366,080円\n\n染症拡大防止を図り、安全に施設利用を\n\n・子育てコミュニティー 87,120円\n\n放課後児童クラブ 75,240円\n\n行うことができている。\n\n・東保育園 502,150円\n\nふれあいセンター 1,061,500円\n\n・西保育園 366,080円\n\n町民体育館 1,122,220円\n\n・放課後児童クラブ 80,520円\n・ふれあいセンター 1,070,300円\n・町民体育館 1,138,060円\n④各保育園、町民体育館 他\n\n30\n\n単\n\n公共施設感染防止対策事業（換気・防虫 ①町民体育館、避難所としても指定されている各小中学\n\nR2.9\n\nR3.3\n\n8,646,000\n\n8,288,000 ・網戸設置工事\n\n【所管課評価】\n\n対策事業）\n\n校体育館の密閉空間解消のための換気対策及び換気時の\n\n関ケ原小学校 514,800円\n\n各施設に網戸を設置することにより換\n\n【教育課】\n\n防虫対策、衛生環境の充実を図るため\n\n今須小中学校 415,800円\n\n気対策を徹底し、また換気時に各体育館\n\n②③網戸設置工事（換気対策）及びLEDライト交換工事\n\n関ケ原中学校 257,400円\n\nの水銀照明に害虫が集まることへの防止\n\n（換気時の防虫対策）に要する経費に充当\n\nのため、LEDライトを設置したことによ\n\n・関ケ原小学校体育館 3,552,230円\n\n・LEDライト交換工事\n\nり、新型コロナウイルス感染症拡大防止\n\n・今須小中学校体育館 4,670,160円\n\n関ケ原小学校・今須小中学校\n\nを図ることができ、安全に施設利用を行\n\n・関ケ原中学校体育館 4,059,330円\n\n3,356,100円\n\nうことができている。\n\n・町民体育館（防虫対策のみ） 4,977,005円\n\n関ケ原中学校 1,789,920円\n\n④各小中学校体育館、町民体育館\n\n町民体育館 2,311,980円\n\n\n",
