        "proof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.4\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n効果検証\n実施状況\n\n【所管課評価】\n【対象者等からの評価】\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n34\n\n①目的・効果\n\n公共施設感染防止対策事業（消耗品整備 ①公共施設における新型コロナウイルス感染症の感染リ\n\n2,070,004\n\n1,984,000 ・感染防止対策消耗品\n\n【所管課評価】\n\n事業）\n\nスクの軽減、拡大防止を図るため\n\n噴霧器（4ℓ×23個） 78,050円\n\n施設入り口に消毒液を常備し、手指消\n\n【総務課】\n\n②③マスクや各公共施設で使用する消毒液等の感染防止\n\nハンドスプレー（1個） 448円\n\n毒を徹底することで、感染リスクを軽減\n\n【医療保健課】\n\nのための消耗品購入経費に充当\n\n消毒液（500mℓ×120本） 40,810円\n\nすることができた。\n\n・噴霧器（4ℓ×23個） 78,050円\n\n消毒液（18ℓ×1本） 16,500円\n\n・ハンドスプレー（1個） 448円\n\nマスク（大人用・26,000枚）\n\n・消毒液（500mℓ×120本） 40,810円\n\n1,207,800円\n\n・消毒液（18ℓ×1本） 16,500円\n\nマスク（子供用・5,000枚）\n\n防止のための衛生用品等の整備を図るこ\n\n・マスク（大人用・26,000枚） 1,207,800円\n\n258,500円\n\nとができた。\n\n・マスク（子供用・5,000枚） 258,500円\n\nスプレーボトル（4ℓ×23個）\n\n・スプレーボトル（4ℓ×23個） 56,100円\n\n56,100円\n\n・テーブル間仕切り用アクリル板（20個） 127,600円\n\nテーブル間仕切り用アクリル板（20個）\n\n・カウンター用間仕切り（27組） 197,406円\n\n127,600円\n\n・フェイスシールド（200枚） 72,600円\n\nカウンター用間仕切り（27組）\n\n・ガンスプレー・ノズル（100個） 14,190円\n\n197,406円\n\n④役場庁舎、関ケ原診療所 他\n\nフェイスシールド（200枚） 72,600円\n\nノンアルコールの手指消毒液は保育園\n児にも安心して使用できた。\nまた、各施設に必要とされる感染拡大\n\nガンスプレー・ノズル（100個）\n14,190円\n35\n\n単\n\nインフルエンザ予防接種助成事業\n\n①新型コロナウイルス感染症とインフルエンザの同時流\n\n【医療保健課】\n\n行に備え、町民の感染予防・重症化予防を図るため\n\nR2.9\n\nR3.3\n\n4,394,360\n\n4,213,000 ・インフルエンザ予防接種委託料\n高齢者 2,031人 3,452,700円\n\n②③インフルエンザ予防接種費用の負担軽減に要する経\n\n妊婦 3人 6,000円\n\nが、今回自己負担金を全額助成したこと\n\n費に充当（医療機関への委託料もしくは本人への助成\n\n子供 431人 862,000円\n\nで接種率70％以上に向上することができ\n\n金）\n\n【所管課評価】\n例年、高齢者は接種率約50％である\n\nた。なお、妊婦50%、小児56.6%の接種\n\n【定期接種分】自己負担分（1,700円）を助成\n\n・インフルエンザ予防接種助成金\n\n率となり、感染予防・重症化予防を図る\n\n・65歳以上、60～64歳障害者等\n\n高齢者 3人 5,100円\n\nことができた。\n\n1,700円×2,034人\n\n妊婦 2人 4,000円\n\n【任意接種分】助成上限額2,000円／回\n\n子供 26人 64,560円\n\n【対象者等からの評価】\n\n・6ヶ月～小学校6年生 2,000円×2回×325人\n\n・同時流行が懸念されていたが、インフ\n\n・中学校1年生～高校3年生 2,000円×1回×240人\n\nルエンザの感染者も例年より少なく、感\n\n・妊婦 2,000円×1回×7人\n\n染予防・重症化予防につながった。\n\n④町民\n\n\n",
