        "evaluatedFiscalYear": 2020,
        "evaluationYear": null,
        "proofStart": 21287,
        "proof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.12\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n効果検証\n実施状況\n\n【所管課評価】\n【対象者等からの評価】\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n38\n\n①目的・効果\n\n地域応援商品券事業\n\n①新型コロナウイルス感染症の拡大による地域事業者へ\n\n【地域振興課】\n\nの経済対策（消費活性化）及び町民の生活支援を図るた\n\n35,369,841\n\n33,906,000 ・ノベルティー等他消耗品 98,047円\n・商品券・ポスター等印刷費\n\n【所管課評価】\n\nめ\n\n769,120円\n\n民が町内の事業所を利用することで地域\n\n②③地域応援商品券（町民1人当たり5,000円分）を発\n\n・商品券郵送代 1,041,674円\n\n内の経済が活性化し、コロナ禍での営業\n\n行・配布する経費に充当\n\n・地域応援商品券換金分\n\n継続を支援することができた。\n\n・ノベルティー等他消耗品 730,000円\n\n33,461,000円\n\n落ち込んだ消費を正常化するために町\n\n・商品券・ポスター等印刷費 882,000円\n\n【対象者等からの評価】\n\n・商品券郵送代 1,358,000円\n\n・普段来ないお客さんが来てくれて、そ\n\n・地域応援商品券換金分 33,530,000円\n\nの後もお店に来てくれるようになった。\n\n④町民\n39\n\n単\n\n社会福祉協議会補助事業\n\n①新型コロナウイルス感染症拡大により、3密対策が十分\n\n【住民課】\n\nに実施できない等の理由により活動が制限されている団\n\nR2.12\n\nR3.3\n\n3,000,000\n\n2,876,000 ・社会福祉協議会補助金\n3,000,000円\n\n体の活動再開を支援するため\n\n【所管課評価】\n広さと空調が確保された空間と移動可\n能なパーテーション等を整備することが\n\n②③社会福祉協議会が実施する活動スペース整備事業に\n\n社教センター・待合ホール等環境\n\nでき、密を回避しながらの事業・会議等\n\n対して補助する経費に充当\n\n改善事業 3,986,510円\n\nの開催が可能となった。\n\n・町社会福祉協議会補助金 3,000,000円\nパーティション設置、空調設備、照明設備工事等\n\n【対象者等からの評価】\n\n4,000,000円（3,000,000万円を上限に補助）\n\n・学習支援事業や小中学校を対象とした\n\n④社会福祉協議会\n\nボランティアスクール事業において、密\nを回避した会場として活用できた。\n\n\n",
        "periodProof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.12\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n効果検証\n実施状況\n\n【所管課評価】\n【対象者等からの評価】\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n38\n\n①目的・効果\n\n地域応援商品券事業\n\n①新型コロナウイルス感染症の拡大による地域事業者へ\n\n【地域振興課】\n\nの経済対策（消費活性化）及び町民の生活支援を図るた\n\n35,369,841\n\n33,906,000 ・ノベルティー等他消耗品 98,047円\n・商品券・ポスター等印刷費\n\n【所管課評価】\n\nめ\n\n769,120円\n\n民が町内の事業所を利用することで地域\n\n②③地域応援商品券（町民1人当たり5,000円分）を発\n\n・商品券郵送代 1,041,674円\n\n内の経済が活性化し、コロナ禍での営業\n\n行・配布する経費に充当\n\n・地域応援商品券換金分\n\n継続を支援することができた。\n\n・ノベルティー等他消耗品 730,000円\n\n33,461,000円\n\n落ち込んだ消費を正常化するために町\n\n・商品券・ポスター等印刷費 882,000円\n\n【対象者等からの評価】\n\n・商品券郵送代 1,358,000円\n\n・普段来ないお客さんが来てくれて、そ\n\n・地域応援商品券換金分 33,530,000円\n\nの後もお店に来てくれるようになった。\n\n④町民\n39\n\n単\n\n社会福祉協議会補助事業\n\n①新型コロナウイルス感染症拡大により、3密対策が十分\n\n【住民課】\n\nに実施できない等の理由により活動が制限されている団\n\nR2.12\n\nR3.3\n\n3,000,000\n\n2,876,000 ・社会福祉協議会補助金\n3,000,000円\n\n体の活動再開を支援するため\n\n【所管課評価】\n広さと空調が確保された空間と移動可\n能なパーテーション等を整備することが\n\n②③社会福祉協議会が実施する活動スペース整備事業に\n\n社教センター・待合ホール等環境\n\nでき、密を回避しながらの事業・会議等\n\n対して補助する経費に充当\n\n改善事業 3,986,510円\n\nの開催が可能となった。\n\n・町社会福祉協議会補助金 3,000,000円\nパーティション設置、空調設備、照明設備工事等\n\n【対象者等からの評価】\n\n4,000,000円（3,000,000万円を上限に補助）\n\n・学習支援事業や小中学校を対象とした\n\n④社会福祉協議会\n\nボランティアスクール事業において、密\nを回避した会場として活用できた。\n\n\n",
