        "proof": "令和2年度 新型コロナウイルス感染症対応地方創生臨時交付金（実施状況及び効果検証）\n補\n\n事業の概要\n\n助\nNo\n\n事業名\n\n･\n\n（所管課）\n\n単\n\n単\n\n②交付金を充当する経費内容\n③積算根拠（対象数、単価等）\n\n事業\n\n事業\n\n始期\n\n終期\n\nR2.12\n\nR3.3\n\n令和2年度\n\n交付金\n\n決算額\n\n充当額\n\n（円）\n\n（円）\n\n効果検証\n実施状況\n\n【所管課評価】\n【対象者等からの評価】\n\n④事業の対象（交付対象者、対象施設等）\n\n独\n40\n\n①目的・効果\n\n情報配信システム導入事業\n\n①新型コロナウイルス感染症の対応に当たり、休校連絡\n\n【教育課】\n\nなどの情報発信や児童の健康状態の把握・管理を効率的\n\n495,000\n\n475,000 ・すぐーる初期導入委託料\n495,000円\n\n【所管課評価】\n保護者との連絡ツールである「すぐー\n\nかつ安全に実施するため\n\nる」を導入することにより、感染予防に\n\n②情報配信システム（情報発信、情報収集のためのアン\n\n関する保護者へのお願いや学校での感染\n\nケート機能等を有するスマホ向けアプリ）の導入に要す\n\n対策などをこまめに通知し、安心を共有\n\nる経費に充当\n\nすることができた。またアンケート機能\n\n③初期導入費用 495,000円\n\nなど各種便利機能を利用し保護者が来校\n\n④保護者\n\nする機会を減らすなど接触防止を図るこ\nとができた。\n\n41\n\n単\n\n公共施設感染防止対策事業（空調設備整 ①児童福祉施設における園児・保育士等の新型コロナウ\n\nR3.3\n\nR3.7\n\n3,083,300\n\n2,800,000 ・保育園空調等整備工事\n3,083,300円\n\n【所管課評価】\n\n備事業）\n\nイルス感染症の感染リスクの軽減、拡大防止を図るため\n\n【住民課】\n\n②③園児室の換気機能付き空調設備の設置及び遊戯室の\n\nり、換気対策や３密回避を図ることがで\n\n空調設備及び換気設備の設置に要する経費に充当\n\nき、十分な新型コロナウイルス感染症予\n\n・保育園空調等整備工事 3,084,290円\n\n防対策に繋がった。\n\n乳児室空調設備（換気機能付き）\n\n各保育園の工事や改修を行うことによ\n\n空調整備の整備により、窓を開け、換\n\nすぎの子園空調設備（換気機能付き）\n\n気をしながら、夏を過ごすことができ\n\n遊戯室空調・換気設備\n\nた。\n\n④各保育園\n\n42\n\n補\n\n学校保健特別対策事業費補助金\n\n（感染症対策等の学校教育活動継続支援事業）\n\nR2.12\n\nR3.3\n\n792,000\n\n380,000 ・小学校備品\n\n【教育課】\n\n加湿器（12台） 792,000円\n\n【所管課評価】\n各学校に加湿器を導入し、加湿するこ\n\n①教育施設における新型コロナウイルス感染症の感染リ\n\nとによって新型コロナウイルスの飛沫飛\n\nスクの軽減、拡大防止を図るため\n\n散を防止し、児童生徒の安全確保を図る\n\n②③感染防止対策に要する経費に充当\n\nことができた。\n\n・小中学校備品（792,000円）\n加湿器 66,000円×12台\n④各小中学校\n\n合計\n\n266,298,898\n\n245,596,000",
